window.DICTIONARY_ENTRY_SHARDS["0064-006e"]={"0064-006e:d637271cf9fe98":{"word":"DNS","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"DNS","de-DE":"DNS"},"forms":[{"form":"DNS","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Desoxyribonukleinsäure"},{"definition":"Direkte Numerische Simulation"},{"definition":"Domain Name System"}],"synonyms":["Desoxyribonukleinsäure","DNA","Erbinformation"],"origins":[],"examples":[{"text":"Die DNS ist ein Makromolekül, das in Lebewesen als Träger der Erbinformation dient.","reference":""},{"text":"„So liefert der Abgleich archaischer DNS mit dem Erbgut heutiger Menschen Aufschluss über deren Abstammungs- und Verwandtschaftsverhältnisse.“","reference":"Frank Patalong: Gekommen, um zu bleiben. In: SPIEGEL GESCHICHTE. Nummer 1, 2023 , Seite 34-39, Zitat Seite 36."},{"text":"Mithilfe der DNS lassen sich instationäre Strömungsvorgänge berechnen.","reference":""},{"text":"Ohne das DNS würde das Internet nicht funktionieren. Es schafft die Verbindung zwischen Domain-Namen (die sich im allgemeinen leicht einprägen) und IP-Adressen.","reference":""}],"idioms":[],"collocations":[],"derivations":["DNS-Name","DNS-Virus"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"DNS","id":"d637271cf9fe98"},"0064-006e:931bce583ae428":{"word":"DNA","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"DNA","de-DE":"DNA"},"forms":[{"form":"DNA","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Desoxyribonukleinsäure, DNS"},{"definition":"Deutscher Normenausschuß, Deutscher Normenausschuss, Deutsches Institut für Normung"}],"synonyms":["Desoxyribonukleinsäure","DNS","Erbinformation"],"origins":["[1] Abkürzung für englisch deoxyribonucleic acid ^(→ en) oder desoxyribonucleic acid ^(→ en)"],"examples":[{"text":"„Allerdings ist die Liste dessen, was man einst als unvermeidlich angesehen, später aber als Unfug erkannt hat, länger als unsere DNA.“","reference":"Yanko Tsvetkov: Atlas der Vorurteile. Knesebeck, München 2013, ISBN 978-3-86873-592-5, Seite 19."},{"text":"„Und sie entdeckten an der Schutzfolie und an den Betonbrocken von der Fahrbahn Spuren einer DNA, die sich auch in der Datenbank des Landeskriminalamts fand.“","reference":"Ingrid Eißele, Isabel Stettin: Wer tut so etwas - und warum?. In: Stern. Nummer Heft 7, 2017 , Seite 96-98, Zitat Seite 97."},{"text":"„Es gelang den Forscherinnen und Forschern, von neun der Toten genügend mitochondriale DNA – das Erbgut der weiblichen Linie – für eine Analyse zu extrahieren.“","reference":"Angelika Franz: Wohnstätte des Bösen. In: SPIEGEL GESCHICHTE. Nummer 1: Die ersten Amerikaner, 2023 , Seite 40-46, Zitat Seite 43."}],"idioms":[],"collocations":[],"derivations":["DNA-Analyse","DNA-Datenbank","DNA-Kopie","DNA-Schaden","DNA-Spur","DNA-Treffer","DNA-Untersuchung","DNA-Virus"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"DNA","id":"931bce583ae428"},"0064-006e:1ea22be1b05f63":{"word":"Dnjepr","partOfSpeech":"Toponym","gender":"der","hyphenation":{"de-CH":"Dnjepr","de-DE":"Dnjepr"},"forms":[{"form":"Dnepr","tags":["alternative"]},{"form":"Dnipro","tags":["variant"]},{"form":"Dnjepr","tags":["Nominativ","Singular"]},{"form":"Dnjeper","tags":["alternative"]},{"form":"Dnjeprs","tags":["Genitiv","Singular"]}],"senses":[{"definition":"mit 2.201 Kilometern der drittlängste Fluss in Europa, der durch Russland, Belarus und die Ukraine fließt"}],"synonyms":["Borysthenes","Danaper","Danapris","Dnepr","Dnipro","Dnjapro"],"origins":[],"examples":[{"text":"„Im Mittelabschnitt ist der Russe nahe der polnischen Grenze, im Süden aber haben unsere Truppen noch nicht einmal den Dnjepr erreicht, obwohl der Fluß dort Hunderte Kilometer nach Osten vorspringt.“","reference":"Wolfgang W. Parth: Vorwärts Kameraden wir müssen zurück. Deutscher Bücherbund, Stuttgart, Seite 291 ."},{"text":"„In Kiew lässt der Konvertit nun alle heidnischen Götterbilder und Statuen zerschlagen oder ins Feuer werfen und befiehlt zudem seinen Untertanen, sich am Ufer des Dnjepr zu einer Massentaufe einzufinden.“","reference":"Ralf Berhorst: Im Dienst des Kaisers. In: GeoEpoche: Die Wikinger. Nummer Heft 53, 2012 , Seite 144-153, Zitat Seite 152."}],"idioms":[],"collocations":[],"derivations":["Dnjepr-Brücke","Dnjepr-Fluss","Dnjepr-Strom"],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Dnjepr","id":"1ea22be1b05f63"},"0064-006e:94c444c47adfea":{"word":"DNVP","partOfSpeech":"Abkürzung","gender":"","hyphenation":{"de-CH":"DNVP","de-DE":"DNVP"},"forms":[{"form":"DNVP","tags":["Nominativ","Singular"]}],"senses":[{"definition":"Deutschnationale Volkspartei"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die DNVP forderte die Regierung auf, den Versailler Vertrag für null und nichtig zu erklären.“","reference":"Frederick Taylor: Inflation. Der Untergang des Geldes in der Weimarer Republik und die Geburt eines deutschen Traumas. 1. Auflage. Siedler Verlag, München 2013, ISBN 9783827500113, Seite 294"},{"text":"„Diese Zuwanderer [Juden aus osteuropäischen Ländern], die ungefähr ein Viertel der 560000 Juden in Deutschland ausmachten, besaßen z.T. die russische oder polnische Staatsbürgerschaft oder waren als ehemalige zaristische Untertanen nun staatenlos. Dies ließ sie zur Zielscheibe einer rigiden staatlichen Ausweisungs- und Internierungspolitik und einer ‹Ostjudenkampagne› der DNVP werden.“","reference":"Werner Bergmann: Geschichte des Antisemitismus. Daten, Fakten, Informationen, Adressen. 3. Auflage. C. H. Beck, München 2006, ISBN 978-3406479878, Seite 76"},{"text":"„Erst von 1928 an übernahmen rechtsstehende Figuren die Führung der DNVP, de schließlich zum Juniorpartner der Nationalsozialisten werden sollte.“","reference":"Tim B. Müller: Die Chance der Demokratie. In: DAMALS. Das Magazin für Geschichte. ISSN 0011-5908, Seite 66 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DNVP","id":"94c444c47adfea"},"0064-006e:17e6b7f90d9467":{"word":"Dnister","partOfSpeech":"Toponym","gender":"der","hyphenation":{"de-CH":"Dnis·ter","de-DE":"Dnis·ter"},"forms":[{"form":"Dnestr","tags":["variant"]},{"form":"Dnister","tags":["Nominativ","Singular"]},{"form":"Dnjestr","tags":["variant"]},{"form":"Dnisters","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ukrainisch-moldawischer Zufluss zum Schwarzen Meer"}],"synonyms":[],"origins":[],"examples":[{"text":"„Der Dnister ist nicht einfach nur ein Fluss. Er ist die Landesgrenze eines Staates, den es eigentlich nicht gibt.“","reference":"wienerzeitung.at: Über ein autoritäres Regime am östlichsten Rand Europas. Abgerufen am 4. September 2017."},{"text":"„Westlich des Dnister ist Rumänisch die offizielle Amtssprache.“","reference":""},{"text":"„Heute hat die Regierung in Chişinău die Kontrolle über das Territorium östlich des Dnister verloren.“","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnister","id":"17e6b7f90d9467"},"0064-006e:5675ac714d742b":{"word":"Dnjepr-Fluss","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dnjepr-Fluss","de-DE":"Dnjepr-Fluss"},"forms":[{"form":"Dneprfluss","tags":["alternative"]},{"form":"Dnepr-Fluss","tags":["alternative"]},{"form":"Dnjepr-Fluß","tags":["obsolete"]},{"form":"Dnjeprfluss","tags":["alternative"]},{"form":"Dnjepr-Flusse","tags":["Dativ","Singular"]},{"form":"Dnjepr-Flusses","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Fluss Dnjepr"}],"synonyms":[],"origins":["Determinativkompositum (verdeutlichendes Kompositum) aus dem Hydronym Dnjepr und dem Substantiv Fluss"],"examples":[{"text":"„Noch vor Sonnenaufgang überquerte das Regiment den Dnjepr-Fluss und machte sich auf den Weg nach Smolensk.“","reference":"Arno Surminski: Der lange Weg.Von der Memel zur Moskwa. Roman. LangenMüller, Stuttgart 2019, ISBN 978-3-7844-3508-4, Seite 108."},{"text":"„Die Dnjepr-Kosaken hatten ihr Lager (‚Setsch‘) hinter den Stromschnellen, die den Dnjepr-Fluss an manchen Stellen besonders gefährlich machen.“","reference":"Hans Wagner: Dnjepr-Melodie. In: Eurasisches Magazin. 30. September 2018, abgerufen am 15. März 2022."},{"text":"„Zur Fußball-Europameisterschaft glänzte Kiew in der Pracht frischer Fassaden und in Lichtspielen im Dnjepr-Fluss.“","reference":"Folgt dem EM-Rausch der Kater? - Ukraine bleibt Arbeit. In: Frankfurter Rundschau. 30. Juni 2012, ISSN 0940-6980 (URL, abgerufen am 15. März 2022) ."},{"text":"„Der 1976 fertiggestellte Kanal vom Dnjepr-Fluss stellt bis zu 85 Prozent des Wasserbedarfs der Krim sicher.“","reference":"Ukraine dreht Krim angeblich das Wasser ab. In: merkur.de. 26. April 2014, ISSN 2510-4179 (URL, abgerufen am 10. April 2022) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnjepr-Fluss","id":"5675ac714d742b"},"0064-006e:e4289d15ef6dd8":{"word":"Dnjepr-Strom","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dnjepr-Strom","de-DE":"Dnjepr-Strom"},"forms":[{"form":"Dneprstrom","tags":["alternative"]},{"form":"Dnepr-Strom","tags":["alternative"]},{"form":"Dnjeprstrom","tags":["alternative"]},{"form":"Dnjepr-Strom","tags":["Nominativ","Singular"]},{"form":"Dnjepr-Strome","tags":["Dativ","Singular"]},{"form":"Dnjepr-Stroms","tags":["Genitiv","Singular"]},{"form":"Dnjepr-Stromes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"großer Fluss Dnjepr"}],"synonyms":[],"origins":["Determinativkompositum (verdeutlichendes Kompositum) aus dem Hydronym Dnjepr und dem Substantiv Strom"],"examples":[{"text":"„Im Tal floss der Dnjepr-Strom und umgab Smolensk wie ein Burggraben.“","reference":"Arno Surminski: Der lange Weg. Von der Memel zur Moskwa. Roman. LangenMüller, Stuttgart 2019, ISBN 978-3-7844-3508-4, Seite 112."},{"text":"„Obwohl das Land am Dnjepr-Strom noch immer zwischen West und Ost gespalten ist, haben die Ukrainer im Gegensatz zu ihren Nachbarn blutige Konflikte im Inneren verhindern können.“","reference":"Hauke Friederichs: Ein schlafender Riese im Niemandsland, stern. Aufgerufen am 14.4.2020."},{"text":"„Der hessische Reisende wiederum schwärmt von der Vier-Millionen-Metropole am Dnjepr-Strom.“","reference":"Heinrich erlebt den Frühling in Kiew, Hersfelder Zeitung, 2.04.12. Aufgerufen am 14.4.2020."},{"text":"„Denn warum sollen denn immer den glatten Strom eueres (und unsers) Lebens entweder Schmerzen oder Sünden brechen, und warum soll er erst wie der Dnjepr-Strom nach dreizehn Wasserfällen im schwarzen Meer der Gruft einsinken?“","reference":"Jean Paul: Siebenkäs. In: Projekt Gutenberg-DE. Drittes Bändchen, Neuntes Kapitel (URL) . Alte Version im Internet-Archiv abrufbar. * Aufgerufen am 14.4.2020."},{"text":"„Was sie taten, war verboten. Sie radelten am gewaltigen Dnjepr-Strom entlang, grüßten freundlich auf Russisch Milizionäre und Soldaten, bei Pannen wurde ihnen geholfen, überhaupt gab es viel Gastfreundschaft, und in Odessa hatten sie ein unverschämtes Glück.“","reference":"Roland Mischke: DDR-Bürger unerkannt in Freundesland, Mainpost, 26. April 2011. Aufgerufen am 14.4.2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnjepr-Strom","id":"e4289d15ef6dd8"},"0064-006e:25c717b25925b4":{"word":"Dnjepr-Brücke","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dnjepr-Brü·cke","de-DE":"Dnjepr-Brü·cke"},"forms":[{"form":"Dneprbrücke","tags":["alternative"]},{"form":"Dnepr-Brücke","tags":["alternative"]},{"form":"Dnjeprbrücke","tags":["alternative"]},{"form":"Dnjepr-Brücke","tags":["Nominativ","Singular"]},{"form":"Dnjepr-Brücken","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Brücke über den Fluss Dnjepr"}],"synonyms":[],"origins":["Determinativkompositum aus dem Toponym (Hydronym) Dnjepr und dem Substantiv Brücke"],"examples":[{"text":"„Die Zarenarmee verließ Smolensk, ohne dass die Franzosen es bemerkten; im Dunkel der Nacht zog sie über die nördlichen Dnjepr-Brücken.“","reference":"Arno Surminski: Der lange Weg. Von der Memel zur Moskwa. Roman. LangenMüller, Stuttgart 2019, ISBN 978-3-7844-3508-4, Seite 118."},{"text":"„Die Flutbrücken und die große Dnjepr-Brücke wurden in der Zeit von 12.00 - 13.00 Uhr gesprengt.“","reference":"Jörg Müller: Die Geschichte des Landkreises Rogachev, 1941 - 1945. Aufgerufen am 15.3.2020."},{"text":"„Die einen sagen, die Leute von Viktor Janukowytsch (dem Rivalen Viktor Juschtschenkos bei den Präsidentschaftswahlen 2004) hätten ihn beseitigt, weil er zuviel über die Wahlmanipulationen wusste, andere, dass sein Tod mit dem Bau der Dnjepr-Brücke zusammenhänge – einem Bauvorhaben, das, obwohl noch nicht begonnen, schon riesige Gelder verschlungen hat.“","reference":"Małgorzata Nocuń, Andzrej Brzeziecki: Östlich von San und Bug. Wo Bahnfahrten noch ein Erlebnis sind ..., OWEP 3/2006. Aufgerufen am 15.3.2020."},{"text":"„Eine Voraussetzung für den Bau der U-Bahn-Linie ist aber die Fertigstellung der Dnjepr-Brücke „Podilsko-Voskresensky Most“, deren Bau bereits 1993 begonnen hatte, dann aber wegen Finanzierungsproblemen gestoppt werden musste.“","reference":"Fabian Nemitz: Ausbau von U-Bahn-Strecken in der Ukraine startet, 22. Februar 2018. Aufgerufen am 15.3.2020."},{"text":"„Dabei kamen wir über die 2 km lange Dnjepr-Brücke.“","reference":"Brief (Transkript): Gerhard Limpach an seine Eltern und Schwester am 26.12.1942 (3.2002.0883), Darniza, den 26.12.42. Aufgerufen am 15.3.2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnjepr-Brücke","id":"25c717b25925b4"},"0064-006e:9f22ebd9b9afe6":{"word":"DNA-Analyse","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"DNA-Ana·ly·se","de-DE":"DNA-Ana·ly·se"},"forms":[{"form":"DNA-Analyse","tags":["Nominativ","Singular"]},{"form":"DNA-Analysen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"(Gesamtheit der) Verfahren zur Untersuchung der Desoxyribonukleinsäure (einer bestimmten Person)"}],"synonyms":["DNA-Test","DNS-Analyse","DNS-Test","Genanalyse","Gentest"],"origins":["Determinativkompositum aus den Substantiven DNA und Analyse"],"examples":[{"text":"„Nofretete, vermutlich die Tochter eines Hofbeamten, heiratet Echnaton, als sie etwa 16 Jahre alt ist. Die Mutter von Echnatons Sohn Tutanchamun ist sie einer DNA-Analyse zufolge aber vermutlich nicht.“","reference":"Hellmuth Vensky: Fundstück 748 – „Bemalte Büste der Königin“. In: Zeit Online. 6. Dezember 2012, ISSN 0044-2070 (URL, abgerufen am 12. April 2020) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"DNA-Analyse","id":"9f22ebd9b9afe6"},"0064-006e:a6336fe5eb1531":{"word":"DNA-Abschnitt","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"DNA-Ab·schnitt","de-DE":"DNA-Ab·schnitt"},"forms":[{"form":"DNA-Abschnitt","tags":["Nominativ","Singular"]},{"form":"DNA-Abschnitte","tags":["Nominativ","Plural"]},{"form":"DNA-Abschnitts","tags":["Genitiv","Singular"]},{"form":"DNA-Abschnitten","tags":["Dativ","Plural"]},{"form":"DNA-Abschnittes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"mehrere Basenpaare der DNA, die zusammen eine Information beinhalten (zum Beispiel ein Gen darstellen)"}],"synonyms":["(bestimmter) Erbfaktor","(eine) Erbanlage","Gen"],"origins":["Kompositum, zusammengesetzt aus DNA und Abschnitt"],"examples":[{"text":"„Als Maß für die Länge eines DNA-Abschnittes wird die Anzahl der Basenpaare (engl. base pairs=bp) oder Nukleotide (nt) angegeben.“","reference":"Die Desoxyribonukleinsäure – Aufbau, Organisation und verschiedene Arten der DNA. Abgerufen am 17. Mai 2020."},{"text":"„Bevor ein Gen transkribiert werden kann, muss der DNA-Abschnitt, der es enthält, zunächst entpackt werden.“","reference":"Fehlender Parameter (Hilfe) Abgerufen am 17. Mai 2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"DNA-Abschnitt","id":"a6336fe5eb1531"},"0064-006e:f3e4a25eb324fc":{"word":"DNS-Analyse","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"DNS-Ana·ly·se","de-DE":"DNS-Ana·ly·se"},"forms":[{"form":"DNS-Analyse","tags":["Nominativ","Singular"]},{"form":"DNS-Analysen","tags":["Nominativ","Plural"]}],"senses":[{"definition":"(Gesamtheit der) Verfahren zur Untersuchung der Desoxyribonukleinsäure (einer bestimmten Person)"}],"synonyms":["DNA-Analyse","DNA-Test","DNS-Test","Genanalyse","Gentest"],"origins":["Determinativkompositum aus den Substantiven DNS und Analyse"],"examples":[{"text":"„Ralf Vermeulen, der Mann, der die DNS-Analyse durchgeführt hat, ist Lizenziat für Biotechnologie.“","reference":"Ralf G. Jahn: Hitlers Familiengeheimnis. GRIN Verlag, 2018, ISBN 978-3-668-74545-2, Seite 58 (Zitiert nach Google Books)"},{"text":"„Durch den Scheidenabstrich konnte Sperma nachgewiesen werden. Eine genaue DNS-Analyse liegt erst nach Weihnachten vor.“","reference":"Alexandra von Grote: Das Fest der Taube: Ein Provence-Krimi - Band 3. dotbooks, 2015, ISBN 978-3-9552077-1-7, Seite 62 (Zitiert nach Google Books)"},{"text":"„Der Erreger lässt sich biochemisch oder mit Hilfe eines ELISA-Schnelltests oder molekulargenetisch durch DNS-Analyse identifizieren.“","reference":"Otfried Siegmann, Ulrich Neumann: Kompendium der Geflügelkrankheiten. Schlütersche, 2014, ISBN 978-3-8426-8529-1, Seite 429 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"DNS-Analyse","id":"f3e4a25eb324fc"},"0064-006e:31d43a63fbf8f8":{"word":"DNA-Impfstoff","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"DNA-Impf·stoff","de-DE":"DNA-Impf·stoff"},"forms":[{"form":"DNA-Impfstoff","tags":["Nominativ","Singular"]},{"form":"DNA-Impfstoffe","tags":["Nominativ","Plural"]},{"form":"DNA-Impfstoffs","tags":["Genitiv","Singular"]},{"form":"DNA-Impfstoffen","tags":["Dativ","Plural"]},{"form":"DNA-Impfstoffes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Vakzin (Impfstoff), das Teile der DNA (Gene) des Krankheitserregers in den Empfänger der Impfung einschleust, wo eigene Körperzellen diese Erbgut-Fragmente (Proteine) vervielfältigen und damit eine Bildung von Antikörpern auslösen, weil das Immunsystem des Empfängers diese DNA-Teile als Antigene erkennt"}],"synonyms":[],"origins":["Determinativkompositum, zusammengesetzt aus DNA und Impfstoff"],"examples":[{"text":"„Statt RNA kann in Impfstoffen auch DNA enthalten sein. Für DNA-Impfstoffe wird das für ein Antigen kodierende Gen in ein nicht replikationsfähiges Expressions-Plasmid eingefügt. Die Vakzinen dieser Art funktionieren wie RNA-Impfstoffe mit dem Unterschied, dass die enthaltene DNA im Körper des Geimpften zunächst im Zellkern in RNA transkribiert werden muss, bevor sie die Bildung von Proteinen veranlassen kann (siehe Grafik).“","reference":"Impfen mit RNA oder DNA, Pharmazeutische Zeitung. Abgerufen am 28. Juli 2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DNA-Impfstoff","id":"31d43a63fbf8f8"},"0064-006e:0c3524bc7ee42b":{"word":"DNA-Virus","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"DNA-Vi·rus","de-DE":"DNA-Vi·rus"},"forms":[{"form":"DNA-Viren","tags":["Nominativ","Plural"]},{"form":"DNA-Virus","tags":["Nominativ","Singular"]},{"form":"DNS-Virus","tags":["variant"]}],"senses":[{"definition":"Krankheitserreger vom Typ Virus, dessen Erbgut/Genom aus einer DNA besteht"}],"synonyms":["DNS-Virus"],"origins":["Kompositum, zusammengesetzt aus DNA und Virus"],"examples":[{"text":"„Viren unterscheiden sich unter anderem darin, in welcher Form ihr Erbmaterial, also die genetische Information des Virus, vorliegt. Bei DNA-Viren besteht das Erbmaterial dem Namen entsprechend aus DNA, also aus Desoxyribonukleinsäure.“","reference":"DNA-Viren. Abgerufen am 3. November 2020."},{"text":"„DNA-Viren replizieren typischerweise im Kern der Wirtszelle und RNA-Viren replizieren typischerweise im Zytoplasma.“","reference":"Viren im Überblick. Abgerufen am 3. November 2020."},{"text":"„EBV ist schwer zu fassen, denn das DNA-Virus durchläuft in seinem Lebenszyklus verschiedene Phasen.“","reference":"Impfstoff gegen Epstein-Barr-Virus. Abgerufen am 3. November 2020."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"DNA-Virus","id":"0c3524bc7ee42b"},"0064-006e:131b4fa52caad6":{"word":"Dnipro","partOfSpeech":"Toponym","gender":"der","hyphenation":{"de-CH":"Dni·pro","de-DE":"Dni·pro"},"forms":[{"form":"Dnepr","tags":["variant"]},{"form":"Dnipro","tags":["Nominativ","Singular"]},{"form":"Dnjepr","tags":["variant"]},{"form":"Dnjeper","tags":["variant"]},{"form":"Dnipros","tags":["Genitiv","Singular"]},{"form":"des Dnipro","tags":["Genitiv","Singular"]},{"form":"des Dnipros","tags":["Genitiv","Singular"]},{"form":"(das) Dnipro","tags":["Nominativ","Singular"]},{"form":"(dem) Dnipro","tags":["Dativ","Singular"]}],"senses":[{"definition":"mit 2.201 Kilometern der drittlängste Fluss in Europa, der durch Russland, Belarus und die Ukraine fließt"},{"definition":"viertgrößte Stadt der Ukraine sowie Hauptort und Verwaltungssitz der Oblast Dnipropetrowsk (Oblast Sitscheslaw)"}],"synonyms":["Borysthenes","Danaper","Danapris","Dnepr","Dnjapro","Dnjepr"],"origins":["transliterierte Entlehnung des ukrainischen Дніпро (Dnipro^☆) ^(→ uk)"],"examples":[{"text":"„Auf dem Steilufer von Kaniv liegt der Grabhügel Taras Schewtschenkos, gemäß seinem ‚Vermächtnis‘ von 1845: Wenn ich sterbe, so bereitet mir mein Grab, Wo die Steppe weit sich breitet in der Ukraine: Daß ich sehe, wie die Felder sich mit Saaten füllen, Daß ich höre, wie der wilde Dnipro rauscht.“","reference":"Volker Janssen: Ein Fluß im Strom der Geschichte. In: Frankfurter Rundschau. 10. April 1999, ISSN 0940-6980, Seite 1 ."},{"text":"„Dagegen ist es völlig ungefährlich, im strengen Kiewer Winter auf dem Eis des Dnipro spazierenzugehen, durch ein Eisloch zu angeln und Brotzeit zu halten; […].“","reference":"Gerhard Gnauck: Bloß nicht aufregen. In: Berliner Morgenpost. 16. Juli 2005, Seite 19 ."},{"text":"„Vor Mariupol, wo es gerade bei der Erstürmung eines Waffendepots zu einer Schießerei gekommen ist, gibt es eine weitere Straßensperre, von einem einsamen Soldaten mit Maschinenpistole bewacht. Das wiederholt sich vor Melitopol, am Übergang über den Dnipro, bei Mykolajew und wiederum kurz vor Odessa.“","reference":"Susanne Beyer (Interviewerin), Karl Schlögel (Interviewter): „Ein schamloser Angriff“. In: DER SPIEGEL. Nummer 19, 5. Mai 2014, ISSN 0038-7452, Seite 117 ."},{"text":"«Ursprünglich gab es am Dnipro, hoch über den Stromschnellen gelegen, eine 1635 errichtete Festung der Zaporoger Kosaken mit dem Namen Kodak.»","reference":"Karl Schlögel: Rocket City am Dnipro. In: Neue Zürcher Zeitung. 6. Dezember 2014, ISSN 0376-6829, Seite 57 ."},{"text":"„Eines zeichnet sich aber in jedem Fall schon ab: 2017 wettete Klitschko nach einem Bericht der ‚Bild‘ mit Berlins Regierendem Bürgermeister Michael Müller (SPD), welcher Langzeitbau der beiden Hauptstädte eher fertig wird – die bereits 1993 begonnene sieben Kilometer lange Brücke über den Fluss Dnipro in Kiew oder der Berliner Hauptstadtflughafen BER, der zum 31. Oktober in Betrieb gehen soll. Die Brücke in Kiew wird nicht vor Jahresende fertig.“","reference":"Siegt Klitschko in der ersten Runde? In: Rhein-Zeitung. 23. Oktober 2020, Seite 2 ."},{"text":"„Je näher sie Kyjiw kamen, desto reger wurde der Verkehr auf dem Fluss. Vor ihnen lag inmitten des Dnipro eine sandige Insel mit einem Strand, zu der drei Motorboote unentwegt Badegäste brachten.“","reference":"Walerjan Pidmohylnyj: Die Stadt. Erste Auflage. Guggolz Verlag, Berlin 2022 (Originaltitel: Місто, übersetzt von Alexander Kratochvil, Lukas Joura, Jakob Wunderwald und Lina Zalitok aus dem Ukrainischen), ISBN 978-3-945370-35-3, Seite 15 (ukrainische Originalausgabe 1928) ."},{"text":"Er lebte seit zehn Jahren in Dnipro.","reference":""},{"text":"„In Dnipro, das von 1926 bis 2016 Dnjepropetrowsk hieß, leben Schätzungen zufolge 40.000 bis 80.000 Juden. Die hiesige Gemeinde ist die größte in der Ukraine und eine Einheitsgemeinde.“","reference":"Jutta Sommerbauer: Jüdisch in Dnipro. In: Jüdische Allgemeine. Wochenzeitung für Politik, Kultur, Religion und jüdisches Leben. 29. August 2019, ISSN 1618-9698, Seite 6 ."},{"text":"„Habeck ist auf Einladung von Selenskyj in der Ukraine unterwegs. Nach dem Treffen mit Selenskyj reiste er am Montag nach Dnipro weiter.“","reference":"AFP/dpa: Habeck will Ukraine mit Defensivwaffen aufrüsten. In: Berliner Zeitung. 26. Mai 2021, ISSN 0947-174X, Seite 4 ."},{"text":"„Ein russischer Luftangriff hat in der Stadt Dnipro eine Schuhfabrik zerstört.“","reference":"Anna-Sophie Schneider: Lera und ihre Katze. In: Spiegel Online. 11. März 2022, ISSN 0038-7452 (URL, abgerufen am 15. März 2022) ."},{"text":"„Dnipro ist die viertgrößte Stadt des Landes und liegt rund 400 Kilometer südöstlich der Hauptstadt Kiew.“","reference":"Simone Schmollack: +++ Nachrichten zum Ukraine-Krieg +++: Russische Kriegsschiffe zerstört. In: taz.de. 25. März 2022, ISSN 2626-5761 (URL, abgerufen am 25. März 2022) ."},{"text":"„Nach dem verheerenden russischen Raketenangriff auf ein Wohnhaus in der ukrainischen Großstadt Dnipro ist die Zahl der Toten auf 40 gestiegen.“","reference":"dpa/AFP/Reuters: Nach russischem Angriff auf Wohnhaus: Zahl der Todesopfer in Dnipro steigt auf 40. In: Der Tagesspiegel Online. 16. Januar 2023 (URL, abgerufen am 24. Februar 2024) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Dnipro","id":"131b4fa52caad6"},"0064-006e:3a37dc37ff0543":{"word":"Dnepr","partOfSpeech":"Toponym","gender":"der","hyphenation":{"de-CH":"Dne·pr","de-DE":"Dne·pr"},"forms":[{"form":"Dnepr","tags":["Nominativ","Singular"]},{"form":"Dneprs","tags":["Genitiv","Singular"]},{"form":"Dnjepr","tags":["alternative"]},{"form":"Dnjeper","tags":["alternative"]}],"senses":[{"definition":"mit 2.201 Kilometern der drittlängste Fluss in Europa, der durch Russland, Weißrussland und die Ukraine führt"}],"synonyms":["Borysthenes","Danaper","Danapris","Dnipro","Dnjapro","Dnjepr"],"origins":[],"examples":[{"text":"„Die Wolga mag inzwischen als Seele Rußlands gelten; die Wiege der Russen, auch der Weißrussen und Ukrainer, bleibt der Dnepr.“","reference":"Thomas Gerlach: Flusskreuzfahrten auf dem Dnepr. Trescher Verlag, 2009, ISBN 978-3-89794-146-5, Seite 16 (Zitiert nach Google Books)"},{"text":"„Eine gute Fahrtstunde südlich von Dnipro liegt die Großstadt Saporischschja an einer weiteren strategisch entscheidenden Stelle am Fluss Dnepr, der die Ost- und die Westukraine teilt.“","reference":"Eleonora Vio: Mit Sandsäcken und Molotowcocktails gegen die russische Armee. In: Spiegel Online. 3. März 2022, ISSN 0038-7452 (URL, abgerufen am 15. März 2022) ."},{"text":"„Russische Truppen rückten in die Hafenstadt Cherson an der Mündung des Dnepr ins Schwarze Meer ein und nahmen die Hafenstadt Mariupol am Asowschen Meer unter Feuer.“","reference":"Paul-Anton Krüger: Ukraine-Krieg: Viele zivile Opfer, schwere Kämpfe um Charkiw. In: sueddeutsche.de. 2. März 2022, ISSN 0174-4917 (URL, abgerufen am 15. März 2022) ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"Dnepr","id":"3a37dc37ff0543"},"0064-006e:1bf385f6e7fb8e":{"word":"Dnjeprbrücke","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dnjepr·brü·cke","de-DE":"Dnjepr·brü·cke"},"forms":[{"form":"Dneprbrücke","tags":["alternative"]},{"form":"Dnepr-Brücke","tags":["alternative"]},{"form":"Dnjeprbrücke","tags":["Nominativ","Singular"]},{"form":"Dnjepr-Brücke","tags":["alternative"]},{"form":"Dnjeprbrücken","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Brücke über den Fluss Dnjepr"}],"synonyms":[],"origins":[],"examples":[{"text":"„Er wollte zu ihr gehen, und als er immer schneller durch die nachtdunklen, verlassenen Straßen Orschas gegen die Dnjeprbrücke ging, wurde seine Sehnsucht immer größer und brennender, bis er schließlich beinahe lief.“","reference":"Heinz G. Konsalik: Strafbataillon 999. Konsalik Verlag, 2020, ISBN 978-3-947022-42-7, Seite 169 (Zitiert nach Google Books)"},{"text":"„Schon sehen wir die beiden südlichen Dnjeprbrücken von Kiew, und schließlich taucht auch der Turm der Zitadelle auf.“","reference":"Illustrierter Beobachter. 1941 (Zitiert nach Google Books)"},{"text":"„Der Präsident des Handelszu ergreifen, um den Bau der Dnjeprbrücke, die nur zur Hälfte amts erklärte, seine Wege und Maßnahmen zu Erkundigungen fertig ist, zu beschleunigen.“","reference":"Verein Deutscher Eisenbahn-Verwaltungen: Zeitung des Vereins deutscher eisenbahnverwaltung. 1907, Seite 209 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnjeprbrücke","id":"1bf385f6e7fb8e"},"0064-006e:a055c0335e86cd":{"word":"Dnepr-Brücke","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dne·pr-Brü·cke","de-DE":"Dne·pr-Brü·cke"},"forms":[{"form":"Dneprbrücke","tags":["alternative"]},{"form":"Dnepr-Brücke","tags":["Nominativ","Singular"]},{"form":"Dnjeprbrücke","tags":["alternative"]},{"form":"Dnepr-Brücken","tags":["Nominativ","Plural"]},{"form":"Dnjepr-Brücke","tags":["alternative"]}],"senses":[{"definition":"Brücke über den Fluss Dnjepr"}],"synonyms":[],"origins":[],"examples":[{"text":"„Wir bewegten uns in Richtung Slobodka, wo wir die Dnepr-Brücke bewachen sollten.“","reference":"Ulrich Schmid: Russland. S. Fischer Verlag, 2017, ISBN 978-3-10-490535-8, Seite 107 (Zitiert nach Google Books)"},{"text":"„Wir rasten zwanzig Minuten durch die nächtliche Stadt, dann hatten wir den alten PAZ-Bus am Ende einer Dnepr-Brücke eingeholt.“","reference":"Oleg Senzow: Haft. Voland & Quist, 2021, ISBN 978-3-86391-327-4, Seite 230 (Zitiert nach Google Books)"},{"text":"„Dann ging es über die Dnepr-Brücke, und wir fragten uns: ‚Wohin geht es nun?‘“","reference":"Walter Eckel: Überleben in Krieg und Gefangenschaft. BoD – Books on Demand, 2011, ISBN 978-3-8423-4367-2, Seite 168 (Zitiert nach Google Books)"},{"text":"„Als Hauptobjekt hätte die Dnepr-Brücke von Kanev gewählt werden müssen.“","reference":"Karl-Heinz Frieser: Die Ostfront 1943/44. Deutsche Verlags-Anstalt, 2007, ISBN 978-3-421-06235-2, Seite 366 (Zitiert nach Google Books)"},{"text":"„Von der Dnepr-Brücke aus verläuft die Straße ziemlich ansteigend und geradewegs in die Stadt Kiew.“","reference":"Bernhard Weber: Erlebnisse in und um Stalins geheimen Atombereich. Verlag Mainz, 1993, ISBN 978-3-925714-83-2, Seite 576 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnepr-Brücke","id":"a055c0335e86cd"},"0064-006e:e0bf826e67a05f":{"word":"Dneprbrücke","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"Dne·pr·brü·cke","de-DE":"Dne·pr·brü·cke"},"forms":[{"form":"Dneprbrücke","tags":["Nominativ","Singular"]},{"form":"Dnepr-Brücke","tags":["alternative"]},{"form":"Dneprbrücken","tags":["Nominativ","Plural"]},{"form":"Dnjeprbrücke","tags":["alternative"]},{"form":"Dnjepr-Brücke","tags":["alternative"]}],"senses":[{"definition":"Brücke über den Fluss Dnjepr"}],"synonyms":[],"origins":[],"examples":[{"text":"„Da bemerken wir, dass die große Dneprbrücke von den Russen bombardiert wurde und brennt.“","reference":"Peter Eberbach: Blut und Elend des Krieges. BoD – Books on Demand, 2014, ISBN 978-3-8391-6835-6, Seite 133 (Zitiert nach Google Books)"},{"text":"„Der seit Ende des Ersten Weltkrieges völlig gesperrte Verkehr zwischen Rumänien und der Sowjetunion wurde mit der Eisenbahnverbindung über eine neue Dneprbrücke bei Tiraspol ' wieder aufgenommen.“","reference":"Matthias Heeke: Reisen zu den Sowjets. LIT Verlag Münster, 2003, ISBN 978-3-8258-5692-2, Seite 134 (Zitiert nach Google Books)"},{"text":"„Wir verabredeten am Fuße der größten der zerstörten Dneprbrücken, und dort traf ich ihn dann eines Morgens.“","reference":"Jonathan Littell: Die Wohlgesinnten. ebook Berlin Verlag, 2010, ISBN 978-3-8270-7036-4, Seite 181 (Zitiert nach Google Books)"},{"text":"„Einem gastfreundlichen Ukrainer verdankten wir es, in Kiew nicht unter eine Dneprbrücke schlafen zu müssen.“","reference":"Frank Bergmann: 5.642. BoD – Books on Demand, 2016, ISBN 978-3-7412-2969-5, Seite 5 (Zitiert nach Google Books)"},{"text":"„Als mit dem Morgen sich in der Lage der Dinge vor Smolensk nichts ånderte, beschloß der Officier fich möglichst nahe an die Dneprbrücke zu begeben, um dort mit irgend einer Gelegenheit in die Stadt zu kommen.“","reference":"Das Buch vom Jahr 1812. 1844, Seite 89 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dneprbrücke","id":"e0bf826e67a05f"},"0064-006e:6cd986b61d0e34":{"word":"Dnjeprfluss","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dnjepr·fluss","de-DE":"Dnjepr·fluss"},"forms":[{"form":"Dneprfluss","tags":["alternative"]},{"form":"Dnjeprfluß","tags":["obsolete"]},{"form":"Dnepr-Fluss","tags":["alternative"]},{"form":"Dnjepr-Fluss","tags":["alternative"]},{"form":"Dnjeprflusse","tags":["Dativ","Singular"]},{"form":"Dnjeprflusses","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Fluss Dnjepr"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die Kämpfer durchschwammen den Dnjeprfluss.“","reference":"Elsa Mahler: Schlüssel zum Lehrbuch der russischen Sprache. Europa Verlag, 1946, Seite 32 (Zitiert nach Google Books)"},{"text":"„Sie liessen sich nahe am Fluss Chortitza nieder, der in den grossen Dnjeprfluss mündet.“","reference":"Peter Goertzen: Teichroeb. Goertzen, 1979, Seite 9 (Zitiert nach Google Books)"},{"text":"„Bei seiner Geburt war die Natur in Aufruhr, ein Untier, Skimen geheissen, kam mit einem ganzen Rudel anderer Bestien ins Land gelaufen, der Dnjeprfluss trat vor Schreck über seine Ufer.“","reference":"Bernhard Stern: Fürst Wladimirs tafelrunde. S. Cronbach, 1892 (Zitiert nach Google Books)"},{"text":"„Margaretha Unger nahm Anteil an der Gründung der MBG, sie ließ sich 1862 von den ersten Mennoniten im Dnjeprfluss taufen, obwohl sie damals schon 67 Jahre alt war […].“","reference":"Johann Epp: Erwecket euren lauteren Sinn. Logos, 2003, ISBN 978-3-933828-93-4, Seite 11 (Zitiert nach Google Books)"},{"text":"„Diese liegen sowohl östlich wie westlich von Nikopol am Dnjeprflusse, und zwar das westliche Vorkommen zwischen einem Nebenfluß des Dnjepr, dem Tschertomlyk, und einem Nebenflusse des Basaluk, dem Solenaja.“","reference":"Berg- und hüttenmännisches Jahrbuch. Springer, 1909, Seite 141 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnjeprfluss","id":"6cd986b61d0e34"},"0064-006e:ffaed8b92070dd":{"word":"Dnepr-Fluss","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dne·pr-Fluss","de-DE":"Dne·pr-Fluss"},"forms":[{"form":"Dnepr-Fluß","tags":["obsolete"]},{"form":"Dneprfluss","tags":["alternative"]},{"form":"Dnjeprfluss","tags":["alternative"]},{"form":"Dnjepr-Fluss","tags":["alternative"]},{"form":"Dnepr-Flusses","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Fluss Dnjepr"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die Stadt wirkt aufgrund ihrer Hanglage am breiten Dnepr-Fluss, der weiten Schneisen und großen Plätze weitläufig und einladend.“","reference":"Heike Maria Johenning: Reise Know-How CityTrip Kiew. Reise Know-How Verlag Peter Rump, 2019, ISBN 978-3-8317-5074-0, Seite 7 (Zitiert nach Google Books)"},{"text":"„Jetzt beansprucht der Kreml-Chef das größte Atomkraftwerk Europas in Saporischschja am Dnepr-Fluss für sich!“","reference":"Oskar Luis Bender: Ihr arbeitet jetzt für uns!. In: Bild.de. 11. März 2022 (URL, abgerufen am 15. März 2022) ."},{"text":"„Die Vorfahren der späteren slawischen Einzelvölker und Stämme begannen zwar schon im 4.-5. Jh. n. Chr. aus der Karpaten-Pripet-Urheimat in allen Himmelsrichtungen abzuwandern (mit Ausnahme Ost und Südost), die relative sprachliche Einheit der weit auseinander siedelnden Gruppen zwischen Nordrußland und Griechenland, zwischen Norditalien und dem Dnepr-Fluß wurde jedoch sehr lange Zeit, zumindest bis zum 11. Jh., teilweise sogar darüber hinaus, aufbewahrt.“","reference":"Denis Sinor: Handbuch Der Orientalistik. BRILL, 1988, Seite 618 (Zitiert nach Google Books)"},{"text":"„Die Hinneigung der Massen nach Moskau schlug ins Gegenteil um, als Moskau hinter dem Rücken der Ukraine 1667 den Vertrag von Andrussowo abschloß, dem zufolge die rechtsseitige Ukraine (d. h. rechts vom Dnepr-Fluß) an Polen und linksseitige an Moskau fallen sollte.“","reference":"Axel Schmidt: Ukraine, Land der Zukunft. R. Hobbing, 1959, Seite 47 (Zitiert nach Google Books)"},{"text":"„Diese »Rhos« waren aus unbekannten Gegenden, fern im Norden des byzantinischen Kulturkreises, mit ihren Booten vom Dnepr-Fluß ins Schwarze Meer gelangt und nach Konstantinopel gerudert.“","reference":"Gerd Stricker: Religion in Russland. Gütersloher Verlagshaus, 1993, ISBN 978-3-579-00634-5, Seite 9 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnepr-Fluss","id":"ffaed8b92070dd"},"0064-006e:e615aa5be214ba":{"word":"Dneprfluss","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dne·pr·fluss","de-DE":"Dne·pr·fluss"},"forms":[{"form":"Dneprfluß","tags":["obsolete"]},{"form":"Dnepr-Fluss","tags":["alternative"]},{"form":"Dneprflusse","tags":["Dativ","Singular"]},{"form":"Dnjeprfluss","tags":["alternative"]},{"form":"Dneprflusses","tags":["Genitiv","Singular"]},{"form":"Dnjepr-Fluss","tags":["alternative"]}],"senses":[{"definition":"Fluss Dnjepr"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die links (hier: östlich) der Fließrichtung des Dneprflusses gelegenen Gebiete des Wilden Felds fallen ab 1667/1686 dauerhaft an Russland.“","reference":"Wikipedia-Artikel „Russisch-Polnische Kriege“ (Stabilversion)"},{"text":"„Nach Constantinos Porphyrogennetos hatten die Unternehmer der Handelsfahrten auf dem Dneprfluss und auf dem schwarzen Meer ihre Heimat ausserhalb des Fürstenthums Kiew, welches er als Russland im engeren Sinn bezeichnet, und zwar in Nowgorod, Smolensk, Lubetsch, Tschernigow, Wyschegrad; aber Kiew war der Sammelplatz der Flotte.“","reference":"Heyd: Geschichte des Levantehandels im Mittelalter. Verlag der J. G. Cotta'schen Buchhandlung, 1879, Seite 82 (Zitiert nach Google Books)"},{"text":"„Denn es war den Tataren in ihren Steppen nicht wohl beizukommen, so lange man sich nicht der Mündungen des Don und des Dneprflusses bemächtigt hatte.“","reference":"Philipp Strahl: Geschichte des russisschen Staates: Von der Regentschaft der Grossfürstin Sophia Alexejewna bis auf die Thronbesteigung der Kaiserin Elisabeth Petrowna (1682-1741). 1849, Seite 23 (Zitiert nach Google Books)"},{"text":"„An dem Dneprfluss gab es sieben gefährliche Stromschnellen, die die Waräger überqueren mussten, um das byzantinische Kaiserreich zu erreichen.“","reference":"Arto Samuel Mustajoki, Jouko Lindstedt: С любовью к слову. Festschrift in Honour of Professor Arto Mustajoki on the Occasion of his 60th Birthday. Department of Slavonic and Baltic Languages and Literatures, University of Helsinki, 2008, Seite 32 (Zitiert nach Google Books)"},{"text":"„Der Kiewer Großfürst Wladimir heiratete die Schwester des byzantinischen Kaisers Basileios II. und musste dafür nach byzantinischem Ritus christlich getauft werden. Er erklärte das Christentum zur Staatsreligion und es kam im Jahr 988 zur besagten Massentaufe im Dneprfluss.“","reference":"Russland und die moralische Verkommenheit des Westens. In: Freiburger Standard. 8. März 2022, abgerufen am 15. März 2022."},{"text":"„Von der Wolga westlich bis zum Dneprflusse breitete sich das Reich der Chasaren aus […].“","reference":"František Palacký: bd. Die urgeschichte und die zeit der herzoge in Böhmen bis zum jahre 1197. In commission bei Kronberger und Weber, 1844, Seite 146 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dneprfluss","id":"e615aa5be214ba"},"0064-006e:42f58c1d14f765":{"word":"Dnepr-Strom","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dne·pr-Strom","de-DE":"Dne·pr-Strom"},"forms":[{"form":"Dneprstrom","tags":["alternative"]},{"form":"Dnepr-Strom","tags":["Nominativ","Singular"]},{"form":"Dnjeprstrom","tags":["alternative"]},{"form":"Dnepr-Stroms","tags":["Genitiv","Singular"]},{"form":"Dnjepr-Strom","tags":["alternative"]},{"form":"Dnepr-Stromes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"großer Fluss Dnjepr"}],"synonyms":[],"origins":[],"examples":[{"text":"„Vor dem Präsidentensitz in Kiew, dort, wo die Straße vom Maidan hinaufsteigt zum Steilufer über dem Dnepr-Strom, demonstrieren Dutzende Menschen.“","reference":"Derbe Heldin. In: Spiegel Online. 6. September 2016, ISSN 0038-7452 (URL, abgerufen am 15. März 2022) ."},{"text":"„Man fährt auf Straßen durch die Wälder östlich der Stadt, und plötzlich erreicht man den Dnepr-Strom.“","reference":"Christian Neef: Stolz, prächtig - und im Aufbruch. In: Spiegel Online. 12. Mai 2017, ISSN 0038-7452 (URL, abgerufen am 15. März 2022) ."},{"text":"„Reisende des 18. und 19. Jahrhunderts, die die Gebiete um den Dnepr-Strom besuchten, geben ihrer Begeisterung über den ungewöhnlichen Reiz der Landschaft und die dem Menschen günstige Ressourcensituation deutlichen Ausdruck.“","reference":"Renate Rolle, Frank M. Andraschko: Frühe Nutzung pflanzlicher Ressourcen. LIT Verlag Münster, 1999, ISBN 978-3-8258-3894-2, Seite 114 (Zitiert nach Google Books)"},{"text":"„Drei von ihnen (Neman-, Minsk- und Dnepr-Strom), die in Litauen und Beloruhland lagen, wurden aus der baltisch-nordschwedischen bzw. finnischen Nährprovinz gespeist.“","reference":"PGM. H. Haack., 1983, Seite 179 (Zitiert nach Google Books)"},{"text":"„Der von Norden nach Süden fließende Dnepr-Strom trennt diese Region von den flachen Ebenen im Osten.“","reference":"Martin Morcinek: Russland nimmt Kiew in die Zange. In: n-tv. 5. März 2022, abgerufen am 15. März 2022."},{"text":"„Ganz besonders bedeutend ist aber der Vorstoß von der Krim im Süden, der doch schon große Geländegewinne gebracht hat und zum Teil über den Dnepr-Strom gegangen ist.“","reference":"Johannes Pressler: Sicherheitsexperte Feichtinger zum Ukraine-Krieg: Situation in Kiew „sehr entscheidend“. In: BuzzFeed. 10. März 2022, abgerufen am 15. März 2022."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnepr-Strom","id":"42f58c1d14f765"},"0064-006e:a30475382fdf58":{"word":"Dnjeprstrom","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dnjeprstrom","de-DE":"Dnjeprstrom"},"forms":[{"form":"Dneprstrom","tags":["alternative"]},{"form":"Dnepr-Strom","tags":["alternative"]},{"form":"Dnjeprstrom","tags":["Nominativ","Singular"]},{"form":"Dnjepr-Strom","tags":["alternative"]},{"form":"Dnjeprstrome","tags":["Dativ","Singular"]},{"form":"Dnjeprstroms","tags":["Genitiv","Singular"]},{"form":"Dnjeprstromes","tags":["Genitiv","Singular"]}],"senses":[{"definition":"großer Fluss Dnjepr"}],"synonyms":[],"origins":[],"examples":[{"text":"„Der Dnjeprstrom bildet eine Hauptverkehrsader zwischen dem Norden und Süden Rußlands.“","reference":"Globus. 1869, Seite 192 (Zitiert nach Google Books)"},{"text":"„Das ist mein altes Sprichwort, und das rettete einmal mein Leben dort unten am Dnjeprstrom.“","reference":"Verner von Heidenstam: Karl der Zwölfte und seine Krieger. BookRix, 2017, ISBN 978-3-7368-7261-5, Seite 215 (Zitiert nach Google Books)"},{"text":"„Wir kamen vor eine große Stadt, an ein großes fließendes Wasser, den Dnjeprstrom, um dort eine große und jetzt sehr berühmte Brücke zu bauen.“","reference":"Fjodor Michailowitsch Dostojewski, Leo Tolstoi, Alexander Sergejewitsch Puschkin, Nikolai Gogol, Michail Lermontow, Anton Pawlowitsch Tschechow, Iwan Sergejewitsch Turgenew, Iwan Gontscharow, Maxim Gorki, Nikolai Leskow, Fjodor Sologub, Wladimir G. Korolenko, Dmitri Mereschkowski, Katharina die Große: Die großen Klassiker der russischen Literatur (30+ Titel in einem Buch). e-artnow, 2016, Seite 8864 (Zitiert nach Google Books)"},{"text":"„Von diesen waren mindestens die Ostgothen, die im Norden des schwarzen Meeres zwischen den Karpathen und dem Dnjeprstrome wohnten, unmittelbare Nachbarn der Slaven, und es ist infolge dessen zu häufigen und heftigen Kämpfen zwischen Slaven und den Ostgothen gekommen.“","reference":"Gustav Strakosch-Grassmann: Geschichte der deutschen in Österreich-Ungarn. C. Konegen, 1895, Seite 299 (Zitiert nach Google Books)"},{"text":"„Mit Sorge dachten sie an die Zukunft des riesigen Landes mit seiner wunderbaren, am majestätischen Dnjeprstrom gelegenen Hauptstadt, die Wauer vor einigen Jahrzehnten, noch vor dem Fall der Berliner Mauer, im Jahr 1985, einmal zusammen mit seiner damaligen geliebten Helga besucht hatte.“","reference":"Christian Friedrich Schultze: Westdämmerung. neobooks, 2017, ISBN 978-3-7427-9593-9, Seite 217 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnjeprstrom","id":"a30475382fdf58"},"0064-006e:f7bdc3252351f6":{"word":"Dneprstrom","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dne·prstrom","de-DE":"Dne·prstrom"},"forms":[{"form":"Dneprstrom","tags":["Nominativ","Singular"]},{"form":"Dnepr-Strom","tags":["alternative"]},{"form":"Dneprstroms","tags":["Genitiv","Singular"]},{"form":"Dnjeprstrom","tags":["alternative"]},{"form":"Dneprstromes","tags":["Genitiv","Singular"]},{"form":"Dnjepr-Strom","tags":["alternative"]}],"senses":[{"definition":"großer Fluss Dnjepr"}],"synonyms":[],"origins":[],"examples":[{"text":"„Denn über den starken Dneprstrom zu schwimmen, das wäre, glaube ich, für die meisten Soldaten Selbstmord gewesen.“","reference":"Alex Wasiliew: Ein Kriegskind aus Russland auf dem langen Weg in seine neue Heimat. Zwiebelzwerg Verlag, 2008, ISBN 978-3-86806-030-0, Seite 62 (Zitiert nach Google Books)"},{"text":"„In einem Kloster, unweit der Hauptstadt Kiew am Dneprstrom, beginnt eine wundersame Erdhöhle.“","reference":"Volkssagen und Märchen der Deutschen und Ausländer. Herausgegeben von Lothar. 1820, Seite 283 (Zitiert nach Google Books)"},{"text":"„Gegen Westen erblickt man ein Stück von Polen und Litthauen, und den die Gränze bestimmten Dneprstrom.“","reference":"Betrachtungen über die neuesten historischen Schriften. 1773, Seite 133 (Zitiert nach Google Books)"},{"text":"„Das sind die Saporoger Kosaken, die ungebärdigen, unbesiegbaren Grenzreiter, die als Freie auf dem Hohen Ufer am Dneprstrom angesiedelt sind, dem Setsch.“","reference":"Gerhard Mackat: Reisen nach Verlorenland. GNN, Gesellschaft für Nachrichtenerfassung und Nachrichtenverbreitung, 2000, ISBN 978-3-89819-044-2, Seite 309 (Zitiert nach Google Books)"},{"text":"„Der Erste ging bis Oleschki (Gouvern. Taurien) der Letzte wahrscheinlich den Dneprstrom hinab bis zu den Mündungen des Dnestr und der Donau und hatte seinen Namen daher, daß er sich durch das schilfige Mündungsland dieser beiden Flüsse hinzog.“","reference":"Konstantin Nikolaevich Bestuzhev-Ri͡umin: Geschichte Russlands. E. Behre, 1874, Seite 197 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dneprstrom","id":"f7bdc3252351f6"},"0064-006e:eaf50e754f2a74":{"word":"Dnestr","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dnestr","de-DE":"Dnestr"},"forms":[{"form":"Dnestr","tags":["Nominativ","Singular"]},{"form":"Dnestrs","tags":["Genitiv","Singular"]},{"form":"Dnister","tags":["variant"]},{"form":"Dnjestr","tags":["variant"]}],"senses":[{"definition":"ukrainisch-moldawischer Zufluss zum Schwarzen Meer"}],"synonyms":[],"origins":[],"examples":[{"text":"„Auch die Erwähnung des Dnestr, dessen Mündungsgebiet am Schwarzen Meer römischem Einfluß unterstand, spricht dafür.“","reference":"Klaus-Peter Johne: Die Römer an der Elbe. Walter de Gruyter, 2014, ISBN 978-3-05-007739-0, Seite 25 (Zitiert nach Google Books)"},{"text":"„Die Krise wurde erst beigelegt, als sich beide Seiten am 30. August 1941 in Tighina einigten, dass Rumänien die volle Souveränität über das ehemals ukrainische Gebiet zwischen Dnestr und Bug (Transnistrien) erhalten, aber dafür auf weitere Abschiebungen von Juden verzichten sollte.“","reference":"Johannes Hürter: Hitlers Heerführer. Walter de Gruyter, 2012, ISBN 978-3-486-70744-1, Seite 589 (Zitiert nach Google Books)"},{"text":"„Wenn dabei trotzdem Leute ums Leben kommen sollten, dann die Söldner, also diejenigen, die in ein fremdes Land gekommen waren, um Krieg zu führen. Mit solchen Mitteln wollte man das Ufer des Dnestrs erobern!“","reference":"Dagmar Wenzel: Jetzt sind wir hier. Zu Hause, e.V, Verein zur gesellschaftlichen Integration von Zuwanderern, 2008, ISBN 978-3-940167-57-6, Seite 255 (Zitiert nach Google Books)"},{"text":"„In das Gebiet des mittleren Dnestrs sind die Anten aus dem Nordosten vorgedrungen, d. h. aus dem Land zwischen dem Dnepr und dem Bug.“","reference":"Byzantinoslavica. Academia, 1976, Seite 152 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnestr","id":"eaf50e754f2a74"},"0064-006e:70e0d97f9412f6":{"word":"Dnjestr","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"Dnjes·tr","de-DE":"Dnjes·tr"},"forms":[{"form":"Dnestr","tags":["variant"]},{"form":"Dnister","tags":["variant"]},{"form":"Dnjestr","tags":["Nominativ","Singular"]},{"form":"Dnjestrs","tags":["Genitiv","Singular"]}],"senses":[{"definition":"ukrainisch-moldawischer Zufluss zum Schwarzen Meer"}],"synonyms":[],"origins":[],"examples":[{"text":"„Diese lebten in der Sommersaison als Jäger und Fischer im Mündungsgebiet des Dnjepr und Dnjestr.“","reference":"Suraiya Faroqhi: Geschichte des Osmanischen Reiches. C.H.Beck, 2021, ISBN 978-3-406-76405-9, Seite 64 (Zitiert nach Google Books)"},{"text":"„Die Gebiete östlich des Dnjestr werden aus der Ukraine gelöst und erhalten den Namen Autonome Moldawische Sozialistische Sowjetrepublik (kurz: MASSR).“","reference":"Hinnerk Dreppenstedt: Flusskreuzfahrten Donau. Trescher Verlag, 2017, ISBN 978-3-89794-373-5, Seite 48 (Zitiert nach Google Books)"},{"text":"„Der dritte Sohn namens Asparuch schließlich habe den Dnjepr und Dnjestr überquert, Flüsse, die nördlich der Donau lägen.“","reference":"Gerlinde Huber-Rebenich, Christian Rohr, Michael Stolz: Wasser in der mittelalterlichen Kultur / Water in Medieval Culture. Walter de Gruyter GmbH & Co KG, 2017, ISBN 978-3-11-043476-7, Seite 132 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnjestr","id":"70e0d97f9412f6"},"0064-006e:c5756176dedf99":{"word":"Dnjeper","partOfSpeech":"Toponym","gender":"der","hyphenation":{"de-CH":"Dnjeper","de-DE":"Dnjeper"},"forms":[{"form":"Dnepr","tags":["alternative"]},{"form":"Dnjepr","tags":["alternative"]},{"form":"Dnjeper","tags":["Nominativ","Singular"]},{"form":"Dnjepers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"mit 2.201 Kilometern der drittlängste Fluss in Europa, der durch Russland, Weißrussland und die Ukraine führt"}],"synonyms":[],"origins":[],"examples":[{"text":"„Die Flüsse des Landes sind der Dnjeper, Dnjester, Bug, Ingul und Inguletz.“","reference":"Alexander J. Schem: Deutsch-Amerikanisches Conversations-Lexikon. Dritter Band. Salzwasser-Verlag, Frankfurt 2020 (Nachdruck des Originals von 1870) (Zitiert nach Google Books)"},{"text":"„Um die Schreckensherrschaft zu brechen, setzten sich seit 16. Februar die Armeen der Mittelmächte noch einmal in Bewegung: aus Galizien und Wolhynien rückten deutsche Truppenteile, denen später auch Österreicher nachfolgten, in die Ukraine ein und säuberten Kiew und alles Gebiet bis an den Dnjeper und das Schwarze Meer einschließlich der Krim von seinen Bedrängern.“","reference":"H. Winter: Der Weltkrieg 1914/18. de Gruyter, 2019 (Nachdruck) (Zitiert nach Google Books)"},{"text":"„Ich glaube, die meisten Rebellen haben Boote gestohlen und sich flussabwärts auf dem Dnjeper davongemacht.“","reference":"Ulf Schiewe: Odins Blutraben. Herrscher des Nordens. Knaur, 2017 (Zitiert nach Google Books)"},{"text":"„Das Herzogtum Warschau, 2778 Quadratmeilen, mit 3 774 000 Einwohnern, wäre nur der kleinere Teil des neuen Reiches gewesen, aber die ehemals polnischen Provinzen reichten bis an die Düna und den Dnjeper.“","reference":"Heinrich Beitzke: Geschichte des Russischen Krieges im Jahre 1812. Europäischer Geschichtsverlag, Paderborn 2015 (Nachdruck) (Zitiert nach Google Books)"},{"text":"„Von Kiev zogen die Ungern weiter über den Dnjeper nach Pannonien, bemächtigten sich desselben und treten unter dem Namen der verheerenden Magyaren in der Geschichte auf.“","reference":"Philipp Strahl: Geschichte des russischen Staates. Erster Band. Von den ältesten Zeiten bis zum Einbruche der Tataren 1224. Friedrich Perthes, Hamburg 1832 (Zitiert nach Google Books)"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"Dnjeper","id":"c5756176dedf99"},"0064-006e:52daf97fc0ff62":{"word":"DNS-Test","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"DNS-Test","de-DE":"DNS-Test"},"forms":[{"form":"DNS-Test","tags":["Nominativ","Singular"]},{"form":"DNS-Tests","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Test, durch den die DNS ermittelt wird"}],"synonyms":["DNA-Analyse","DNA-Test","DNS-Analyse","Genanalyse","Gentest"],"origins":["Determinativkompositum aus den Substantiven DNS und Test"],"examples":[{"text":"„Dein DNS-Test zeigt einen lebenden Verwandten an.“","reference":"Futurama, Space Pilot 3000, 1999 (Filmuntertitel); zitiert nach: Digitales Wörterbuch der deutschen Sprache „DNS-Test“"}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation","openthesaurus"],"sourceWord":"DNS-Test","id":"52daf97fc0ff62"},"0064-006e:ca8808ec82ff56":{"word":"DNA-Datenbank","partOfSpeech":"Substantiv","gender":"die","hyphenation":{"de-CH":"DNA-Da·ten·bank","de-DE":"DNA-Da·ten·bank"},"forms":[{"form":"DNA-Datenbank","tags":["Nominativ","Singular"]},{"form":"DNA-Datenbanken","tags":["Nominativ","Plural"]}],"senses":[{"definition":"Sammlung von genetischen Informationen"}],"synonyms":[],"origins":["Determinativkompositum aus DNA und Datenbank"],"examples":[{"text":"„Während zu fast 2.000 der untersuchten Pflanzen bereits genetische Informationen in öffentlich zugänglichen DNA-Datenbanken vorlagen, wurden mehr als 800 Blütenpflanzen zum ersten Mal überhaupt genetisch sequenziert.“","reference":"Anna Manz: Neuer Stammbaum für die Blütenpflanzen. In: scinexx.de. 25. April 2024, abgerufen am 11. August 2024."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DNA-Datenbank","id":"ca8808ec82ff56"},"0064-006e:30b720474f966f":{"word":"DNA-Treffer","partOfSpeech":"Substantiv","gender":"der","hyphenation":{"de-CH":"DNA-Tref·fer","de-DE":"DNA-Tref·fer"},"forms":[{"form":"DNA-Treffer","tags":["Nominativ","Singular"]},{"form":"DNA-Treffern","tags":["Dativ","Plural"]},{"form":"DNA-Treffers","tags":["Genitiv","Singular"]}],"senses":[{"definition":"Übereinstimmung von zwei DNA-Proben, positive Identifizierung aufgrund der DNA"}],"synonyms":[],"origins":[],"examples":[{"text":"„Hat man noch ein paar Kleinigkeiten wie die Mordwaffe, Fingerabdrücke und einen DNA-Treffer, ja dann, Hergott, hat man auch Geschworene, die ohne Skrupel einen Schuldspruch fällen.“","reference":"David Simon: Homicide. Ein Jahr auf mörderischen Straßen. Antje Kunstmann, München 2011, ISBN 978-3-888-97723-7, Seite 574 ."}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DNA-Treffer","id":"30b720474f966f"},"0064-006e:ce6b89964e9658":{"word":"DN","partOfSpeech":"Abkürzung","gender":"die","hyphenation":{"de-CH":"DN","de-DE":"DN"},"forms":[],"senses":[{"definition":"Kraftfahrzeugkennzeichen für den Kreis Düren"}],"synonyms":[],"origins":[],"examples":[{"text":"Warum steht dasFahrzeug mit dem Kennzeichen DN ABC 7 auf meinem Privatparkplatz?","reference":""}],"idioms":[],"collocations":[],"derivations":[],"sourceIds":["wiktionary","hyphenation"],"sourceWord":"DN","id":"ce6b89964e9658"}};
